def precise(points,dt=.05,cameras=['practice_cam'],name='precise'):
    global seq,last,pos
    a=np.asarray(points,float)
    if a.shape[1]==3:a=np.c_[a,np.tile(Q,(len(a),1))]
    q=last.group('joint_pos',now=True)
    qs=[]
    for p in a:
        sol=r.ik({'tip':p.tolist()},seed=q,tol_pos_m=0.00001,tol_rot_rad=.0001,max_iters=200)
        if not sol['ok']:raise RuntimeError(sol)
        q=sol['q'];qs.append(q)
    for start in range(0,len(qs),int(10/dt)):
        chunk=qs[start:start+int(10/dt)];seq+=1
        np.save(f'{OUT}/actions_{seq:03d}.npy',chunk)
        np.save(f'{OUT}/poses_{seq:03d}.npy',a[start:start+len(chunk)])
        with open(f'{OUT}/commands.log','a') as f:f.write(json.dumps({'seq':seq,'name':name,'type':'joint_position','dt':dt,'rows':len(chunk)})+'\n')
        last=r.submit('joint_position',chunk,dt=dt,cameras=cameras,video='frames',video_fps=10,note=name)
        last.save(f'{OUT}/run_{seq:03d}')
        for c,im in last.last.items():Image.fromarray(im).save(f'{OUT}/{c}.png')
        pos=np.array(last.group('tcp_pose',now=True)[:3])
        print('EXEC',seq,name,'pos',pos,'left',last.meta.get('time_left_s'),flush=True)
    return last

def line(p,speed=.01,hold=.2,**kwargs):
    p=np.array(p);n=max(1,int(np.ceil(np.linalg.norm(p-pos)/speed/.05)))
    a=np.linspace(pos,p,n+1)[1:];a=np.r_[a,np.tile(p,(int(hold/.05),1))]
    return precise(a,**kwargs)

def calibration():
    for i,d in enumerate([.001,.002,.004,.006,.009,.012]):
